import json

facts = {
    ("suspects", "duck", "butterfly"),
    ("named", "fish", "Paco"),
    ("named", "reindeer", "Peddi"),
    ("not_hugs", "ant", "flamingo"),
}
evidence = []

while True:
    additions = set()

    fish_names = [f[2] for f in facts if f[:2] == ("named", "fish")]
    reindeer_names = [f[2] for f in facts if f[:2] == ("named", "reindeer")]
    if any(a and b and a[0] == b[0]
           for a in reindeer_names for b in fish_names):
        additions.add(("hugs", "reindeer", "crab"))

    for fact in facts:
        if len(fact) == 3 and fact[0] == "suspects" and fact[2] == "butterfly":
            additions.add(("suspects", fact[1], "otter"))

    if ("not_hugs", "ant", "flamingo") in facts:
        additions.add(("reveals_secret", "flamingo", "otter"))

    if {
        ("reveals_secret", "flamingo", "otter"),
        ("suspects", "duck", "otter"),
    } <= facts:
        additions.add(("not_hides_cards", "otter", "dragon"))

    new = additions - facts
    if not new:
        break
    evidence.extend(sorted(new))
    facts.update(new)

positive = ("hides_cards", "otter", "dragon") in facts
negative = ("not_hides_cards", "otter", "dragon") in facts

if positive and negative:
    print("UNSUPPORTED")
else:
    answer = "proved" if positive else "disproved" if negative else "unknown"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "derived": evidence,
            "query_supported": positive,
            "negation_supported": negative
        }
    }, separators=(",", ":")))
